SELECT 

FROM bid_template
WHERE 1=1

    AND template_no LIKE CONCAT('%', #{param.templateNo}, '%')


    AND template_name LIKE CONCAT('%', #{param.templateName}, '%')


    AND template_type = #{param.templateType}


    AND template_category = #{param.templateCategory}


    AND template_status = #{param.templateStatus}


    AND approval_status = #{param.approvalStatus}


    AND is_default = #{param.isDefault}


    AND is_enabled = #{param.isEnabled}


    AND author_id = #{param.authorId}


    AND author_name LIKE CONCAT('%', #{param.authorName}, '%')


    AND reviewer_id = #{param.reviewerId}


    AND approver_id = #{param.approverId}


    AND complexity_level = #{param.complexityLevel}


    AND usage_count >= #{param.minUsageCount}


    AND usage_count <= #{param.maxUsageCount}


    AND rating_score >= #{param.minRatingScore}


    AND rating_score <= #{param.maxRatingScore}


    AND review_date >= #{param.reviewStartDate}


    AND review_date <= #{param.reviewEndDate}


    AND approval_date >= #{param.approvalStartDate}


    AND approval_date <= #{param.approvalEndDate}


    AND last_used_date >= #{param.lastUsedStartDate}


    AND last_used_date <= #{param.lastUsedEndDate}


    AND create_time >= #{param.createStartTime}


    AND create_time <= #{param.createEndTime}


    AND create_by = #{param.createBy}


    AND (template_no LIKE CONCAT('%', #{param.keyword}, '%')
         OR template_name LIKE CONCAT('%', #{param.keyword}, '%')
         OR template_description LIKE CONCAT('%', #{param.keyword}, '%')
         OR author_name LIKE CONCAT('%', #{param.keyword}, '%')
         OR template_tags LIKE CONCAT('%', #{param.keyword}, '%')
         OR keywords LIKE CONCAT('%', #{param.keyword}, '%')
         OR remarks LIKE CONCAT('%', #{param.keyword}, '%'))

ORDER BY create_time DESC, id DESC

SELECT COUNT(1) > 0
FROM bid_template
WHERE template_no = #{templateNo}

    AND id != #{excludeId}

SELECT
FROM bid_template WHERE (template_no LIKE CONCAT('%', #{keyword}, '%') OR template_name LIKE CONCAT('%', #{keyword}, '%') OR template_description LIKE CONCAT('%', #{keyword}, '%') OR template_tags LIKE CONCAT('%', #{keyword}, '%') OR keywords LIKE CONCAT('%', #{keyword}, '%')) AND is_enabled = 1 ORDER BY usage_count DESC, rating_score DESC
LIMIT #{limit}

SELECT COUNT(*) as totalCount, COUNT(CASE WHEN template_status = 1 THEN 1 END) as draftCount, COUNT(CASE WHEN template_status = 2 THEN 1 END) as publishedCount, COUNT(CASE WHEN template_status = 3 THEN 1 END) as archivedCount, COUNT(CASE WHEN is_enabled = 1 THEN 1 END) as enabledCount, COUNT(CASE WHEN is_default = 1 THEN 1 END) as defaultCount, COUNT(CASE WHEN approval_status = 1 THEN 1 END) as pendingApprovalCount, COUNT(CASE WHEN approval_status = 2 THEN 1 END) as approvedCount, COUNT(CASE WHEN approval_status = 3 THEN 1 END) as rejectedCount, COALESCE(SUM(usage_count), 0) as totalUsageCount, COALESCE(SUM(download_count), 0) as totalDownloadCount, COALESCE(AVG(rating_score), 0) as avgRatingScore, COALESCE(AVG(usage_count), 0) as avgUsageCount FROM bid_template WHERE 1=1
AND template_type = #{param.templateType}
AND template_status = #{param.templateStatus}
AND author_id = #{param.authorId}
AND create_time >= #{param.createStartTime}
AND create_time <= #{param.createEndTime}

SELECT template_type as templateType, COUNT(*) as count, COALESCE(SUM(usage_count), 0) as totalUsageCount, COALESCE(AVG(rating_score), 0) as avgRatingScore, COUNT(CASE WHEN is_enabled = 1 THEN 1 END) as enabledCount FROM bid_template WHERE 1=1
AND template_status = #{param.templateStatus}
AND author_id = #{param.authorId}
AND create_time >= #{param.createStartTime}
AND create_time <= #{param.createEndTime}
GROUP BY template_type ORDER BY count DESC

SELECT
    template_status as templateStatus,
    COUNT(*) as count,
    COALESCE(SUM(usage_count), 0) as totalUsageCount,
    COALESCE(AVG(rating_score), 0) as avgRatingScore
FROM bid_template
WHERE 1=1

    AND template_type = #{param.templateType}


    AND author_id = #{param.authorId}


    AND create_time >= #{param.createStartTime}


    AND create_time <= #{param.createEndTime}

GROUP BY template_status
ORDER BY template_status

SELECT author_id as authorId, author_name as authorName, COUNT(*) as count, COALESCE(SUM(usage_count), 0) as totalUsageCount, COALESCE(AVG(rating_score), 0) as avgRatingScore, COUNT(CASE WHEN is_enabled = 1 THEN 1 END) as enabledCount FROM bid_template WHERE 1=1
AND template_type = #{param.templateType}
AND template_status = #{param.templateStatus}
AND create_time >= #{param.createStartTime}
AND create_time <= #{param.createEndTime}
GROUP BY author_id, author_name ORDER BY count DESC

SELECT DATE_FORMAT(last_used_date, '%Y-%m') as month, COUNT(DISTINCT id) as templateCount, COALESCE(SUM(usage_count), 0) as totalUsageCount, COALESCE(SUM(download_count), 0) as totalDownloadCount FROM bid_template WHERE last_used_date >= DATE_SUB(SYSDATE, INTERVAL 12 MONTH)
AND template_type = #{param.templateType}
AND template_status = #{param.templateStatus}
GROUP BY DATE_FORMAT(last_used_date, '%Y-%m') ORDER BY month

